INSERT INTO feature VALUES('side-view','editor','The terminal side view','engine-hub','implemented','ordinary',NULL,'`gandr view` follows the hub''s render bus beside an editor, showing each document''s highlights, then one row per declaration of its account, then its diagnostic cards, then the stack at the editor''s cursor, and under `--trace` the derivation pane at the cursor, so a card that comes or goes moves no row of the account. A row holds the kernel warrant''s glyph in its hue, the tier, the verdict, and the sparkline of its timings when the account holds them.','surface-tui surface-render-remote','crates/surface-render-remote/src/lib.rs crates/surface-tui/src/follow.rs',NULL,'#126');
